Q: How to get current language code with Swift? A: <p>I created this extensions</p>
<pre class="lang-swift prettyprint-override"><code>fileprivate extension Locale {
    func localizedName(for languageCode: String) -&gt; String {
        guard let name = self.localizedString(forLanguageCode: languageCode) else {
            return languageCode
        }
        return name
    }

    static func localizedName(for languageCode: String, in locale: Locale = .current) -&gt; String {
        return locale.localizedString(forLanguageCode: languageCode) ?? languageCode
    }
}
</code></pre>
<p>How to use:</p>
<pre class="lang-swift prettyprint-override"><code>// 1. Instance method (called on an existing object)
let spanishLocale = Locale(identifier: &quot;es_ES&quot;)
let name1 = spanishLocale.localizedName(for: &quot;fr&quot;) 
print(name1) // &quot;francés&quot;

// 2. Static method (called directly on the Locale type)
let name2 = Locale.localizedName(for: &quot;fr&quot;) 
print(name2) // &quot;French&quot; (uses .current)

let frenchLocale = Locale(identifier: &quot;fr_FR&quot;)
let name3 = Locale.localizedName(for: &quot;en&quot;, in: frenchLocale) 
print(name3) // &quot;anglais&quot;
</code></pre>
<p>If you need from NSLanguage</p>
<pre class="lang-swift prettyprint-override"><code>fileprivate extension NLLanguage {

    func localizedName(in locale: Locale) -&gt; String {
        locale.localizedString(forLanguageCode: rawValue) ?? rawValue
    }
}
</code></pre>
